var questions=[["有件事一直没动手，最常卡在哪儿？", ["事情太大，不知道从哪儿下手", "坐下了，又去看别的东西", "怕做得不好，迟迟不敢开始", "觉得有点闷，想找个人一起做"]], ["只留十分钟，你愿意先做什么？", ["把任务拆成两三个小步骤", "收起手机，打开需要的文件", "随便写一版，先不管好不好", "和朋友说说我准备做什么"]], ["新任务到手，你最想先有？", ["一张能看懂的步骤清单", "一块不被打扰的时间", "一个可以改的粗糙初稿", "一个能问问题的人"]], ["哪句话最能让你愿意动一下？", ["先做最小的那一步就行", "这十分钟，只做这一件", "第一版不用好，先有再改", "我也正要做，一起开始吧"]], ["已经开始后，什么最容易打断你？", ["下一步又不知道该做什么", "提醒和消息一直跳出来", "反复修改开头，总觉得不够好", "卡住了没人聊，越想越难"]], ["现在就选一个动作，你选？", ["写下第一步，具体到能马上做", "关掉无关页面，留一个窗口", "写三行难看的草稿", "约人各做十分钟，再说说进展"]]];var results=[["先把第一步写小一点", "你刚才选了好几次“先弄清怎么做”。", "把“写报告”换成“打开文件，列三个小标题”。只定下一步，做完再看后面。", "现在试试：写下一件两分钟就能开始的小动作。"], ["留一小块清静时间", "你刚才更想少受一点打扰。", "收起手机，关掉无关页面，只留今天要用的文件。先做十分钟，到点再决定要不要继续。", "现在试试：把桌面上最分心的一样东西挪远。"], ["先做一版，不急着做好", "你刚才好几次选了“先有个初稿”。", "写作就先写三句，做图就先放好几个元素。第一轮只把东西放上去，下一轮再挑着改。", "现在试试：给自己留一个“这里以后再改”的位置，接着往下做。"], ["找个人一起开个头", "你刚才更愿意边聊边开始。", "约一个熟人，各自做十分钟。开始前说要做什么，结束后说做到哪儿，不用互相监督一整天。", "现在试试：发一句“我想先做十分钟，你要不要一起？”"]];